// Average price of the items in a cart.
export function average(prices) {
  return prices.reduce((sum, p) => sum + p, 0) / prices.length;
}

// What the shopper pays: 10% off carts over 100.
export function total(prices) {
  const sum = prices.reduce((s, p) => s + p, 0);
  return sum > 100 ? sum * 0.9 : sum;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total } from '../src/cart.mjs';

test('carts over 100 get 10% off', () => {
  assert.equal(total([60, 60]), 108);
});

test('carts of exactly 100 pay full price', () => {
  assert.equal(total([50, 50]), 100);
});
